-- Final review of the open 2026-11-01 review rows (scripts/review-final.mjs verdicts, every
-- written value checked against SALDO; manual decisions with their evidence). Archived;
-- :'batch' is the archive batch id.
begin;
create temp table w (id uuid, slot text, value text, reason text) on commit drop;
create temp table d (id uuid, slot text, reason text) on commit drop;
select :'batch'::uuid, w.id, 'word_forms', w.slot, f.form_value, w.value, 'final_review:' || w.reason
from w left join public.word_forms f on f.learning_object_id = w.id and f.form_type = w.slot;
update public.word_forms f set form_value = w.value, updated_at = now() from w where f.learning_object_id = w.id and f.form_type = w.slot;
select w.id, w.slot, w.value, 50 from w where not exists (select 1 from public.word_forms f where f.learning_object_id = w.id and f.form_type = w.slot);
select :'batch'::uuid, f.learning_object_id, 'deleted:word_forms', f.form_type, row_to_json(f)::text, null, 'final_review:' || d.reason
from d join public.word_forms f on f.learning_object_id = d.id and f.form_type = d.slot;
delete from public.word_forms f using d where f.learning_object_id = d.id and f.form_type = d.slot;
update public.content_suggestions set status = 'rejected', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: This is a false positive: Swedish also has the noun anställd ‘employee’, so part_of_speech noun is valid.', reviewed_at = now() where id = '188' and status = 'pending';
update public.content_suggestions set status = 'rejected', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: The Swedish explanation is valid Swedish; the flag is a false positive.', reviewed_at = now() where id = '207' and status = 'pending';
update public.content_suggestions set status = 'applied', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: adverb entry (på förhand): the noun forms belong to the noun förhand..nn.1', reviewed_at = now() where id = '210' and status = 'pending';
update public.content_suggestions set status = 'applied', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: adverb entry (i åratal): the noun forms belong to the noun åratal..nn.1', reviewed_at = now() where id = '221' and status = 'pending';
update public.content_suggestions set status = 'rejected', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: The stored Swedish explanation is valid Swedish, so the flag is a false positive.', reviewed_at = now() where id = '222' and status = 'pending';
update public.content_suggestions set status = 'rejected', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: False positive: the example clearly contains the headword "o.s.v.".', reviewed_at = now() where id = '268' and status = 'pending';
update public.content_suggestions set status = 'rejected', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: The Swedish explanation is valid Swedish; the flag is a false positive.', reviewed_at = now() where id = '273' and status = 'pending';
update public.content_suggestions set status = 'applied', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: onter/onterna are not forms of ont (SALDO ont..nn.1: ont, onten); the entry is uncountable', reviewed_at = now() where id = '274' and status = 'pending';
update public.content_suggestions set status = 'rejected', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: the example uses värmlandsdialekt (false positive)', reviewed_at = now() where id = '276' and status = 'pending';
update public.content_suggestions set status = 'rejected', note = coalesce(note || ' | ', '') || 'final review 2026-11-01: The stored Swedish explanation is valid Swedish, so the flag is a false positive.', reviewed_at = now() where id = '293' and status = 'pending';
commit;
